1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keep — Save a bookmark</title>
7	  <style>
8	    :root { color-scheme: light; --ink:#17201d; --muted:#68736e; --line:#dfe6e2; --paper:#fff; --wash:#f3f6f3; --green:#28664f; --green2:#e5f1eb; }
9	    * { box-sizing: border-box; }
10	    body { margin:0; min-height:100vh; background:var(--wash); color:var(--ink); font:15px/1.5 Inter, ui-sans-serif, system-ui, sans-serif; }
11	    header { height:68px; background:var(--paper); border-bottom:1px solid var(--line); display:flex; align-items:center; padding:0 5vw; }
12	    .brand { font:700 21px/1.2 Georgia, serif; letter-spacing:.01em; }
13	    .brand i { display:inline-block; width:11px; height:15px; margin-right:9px; background:var(--green); border-radius:2px 2px 5px 5px; vertical-align:-2px; }
14	    main { width:min(760px, 90vw); margin:72px auto; }
15	    .eyebrow { color:var(--green); font-weight:700; letter-spacing:.1em; text-transform:uppercase; font-size:12px; }
16	    h1 { font:600 clamp(34px, 5vw, 52px)/1.08 Georgia, serif; margin:12px 0 12px; letter-spacing:-.025em; }
17	    .lede { color:var(--muted); font-size:17px; margin:0 0 32px; }
18	    .panel { background:var(--paper); border:1px solid var(--line); border-radius:18px; padding:24px; box-shadow:0 18px 48px rgba(25,48,39,.07); }
19	    label { display:block; font-weight:700; margin-bottom:8px; }
20	    .urlrow { display:flex; gap:10px; }
21	    input { width:100%; height:48px; border:1px solid #c8d2cd; border-radius:10px; padding:0 14px; font:inherit; color:var(--ink); outline:none; }
22	    input:focus { border-color:var(--green); box-shadow:0 0 0 3px var(--green2); }
23	    button { border:0; border-radius:10px; padding:0 20px; font:700 15px/1 system-ui,sans-serif; cursor:pointer; }
24	    .primary { height:48px; color:white; background:var(--green); min-width:142px; }
25	    .primary:hover { background:#1f5641; }
26	    .hint { color:var(--muted); font-size:13px; margin:9px 0 0; }
27	    .preview { display:none; margin-top:22px; padding-top:22px; border-top:1px solid var(--line); }
28	    .preview.show { display:block; }
29	    .meta { font-size:12px; color:var(--green); font-weight:700; margin-bottom:5px; }
30	    .title { font:600 22px/1.25 Georgia,serif; margin:0 0 7px; }
31	    .desc { color:var(--muted); margin:0; }
32	    .actions { display:flex; justify-content:flex-end; gap:10px; margin-top:22px; }
33	    .ghost { height:42px; background:transparent; color:var(--muted); }
34	    .save { height:42px; background:var(--green); color:white; }
35	    .success { display:none; align-items:center; gap:13px; }
36	    .success.show { display:flex; }
37	    .check { width:38px; height:38px; border-radius:50%; background:var(--green2); color:var(--green); display:grid; place-items:center; font-size:21px; font-weight:800; }
38	    .success strong { display:block; }
39	    .success span { color:var(--muted); font-size:13px; }
40	    @media (max-width:560px) { main { margin-top:42px; } .urlrow { flex-direction:column; } .primary { width:100%; } }
41	  </style>
42	</head>
43	<body>
44	  <header><div class="brand"><i></i>Keep</div></header>
45	  <main data-harness-ready="true">
46	    <div class="eyebrow">Your library</div>
47	    <h1>Save something worth finding again.</h1>
48	    <p class="lede">Paste a link and its details will be filled in for you.</p>
49	    <section class="panel" aria-live="polite">
50	      <div id="form">
51	        <label for="url">Web address</label>
52	        <div class="urlrow">
53	          <input id="url" type="url" placeholder="https://example.com/article" autocomplete="off">
54	          <button class="primary" id="fetch">Get details</button>
55	        </div>
56	        <p class="hint">For this prototype, any complete web address will show an example preview.</p>
57	        <div class="preview" id="preview">
58	          <div class="meta" id="domain">THE MARGINALIAN</div>
59	          <h2 class="title">How to live with presence in an age of productivity</h2>
60	          <p class="desc">A thoughtful reflection on attention, purpose, and the quiet work of being fully alive.</p>
61	          <div class="actions">
62	            <button class="ghost" id="cancel">Cancel</button>
63	            <button class="save" id="save">Save bookmark</button>
64	          </div>
65	        </div>
66	      </div>
67	      <div class="success" id="success">
68	        <div class="check">✓</div>
69	        <div><strong>Bookmark saved</strong><span>The title and description are now in your library.</span></div>
70	      </div>
71	    </section>
72	  </main>
73	  <script>
74	    const url = document.querySelector('#url');
75	    const preview = document.querySelector('#preview');
76	    const form = document.querySelector('#form');
77	    const success = document.querySelector('#success');
78	    const domain = document.querySelector('#domain');
79	    document.querySelector('#fetch').addEventListener('click', () => {
80	      if (!url.value.trim()) { url.focus(); return; }
81	      try { domain.textContent = new URL(url.value).hostname.replace(/^www\./,'').toUpperCase(); } catch { domain.textContent = 'SAVED PAGE'; }
82	      preview.classList.add('show');
83	    });
84	    document.querySelector('#cancel').addEventListener('click', () => preview.classList.remove('show'));
85	    document.querySelector('#save').addEventListener('click', () => { form.style.display='none'; success.classList.add('show'); });
86	  </script>
87	</body>
88	</html>
