    .suggestions { display:none; position:absolute; z-index:2; width:100%; top:48px; background:#fff; border:1px solid #c8d2cd; border-radius:9px; padding:5px; box-shadow:0 12px 28px rgba(25,48,39,.13); }
    .suggestions.show { display:block; }
    .suggestion { width:100%; height:36px; background:#fff; color:var(--ink); text-align:left; padding:0 10px; }
    .suggestion:hover { background:var(--green2); }
    @media (max-width:560px) { main { margin-top:42px; } .urlrow { flex-direction:column; } .primary { width:100%; } .card-preview { grid-template-columns:1fr; } .thumb { height:150px; } }
