              <div class="field">
                <label for="title">Title</label>
                <input id="title" value="How to live with presence in an age of productivity">
              </div>
              <div class="field">
                <label for="description">Description</label>
                <textarea id="description">A thoughtful reflection on attention, purpose, and the quiet work of being fully alive.</textarea>
              </div>
              <div class="tag-editor">
                <div class="field">
                  <label for="tag-input">Tags</label>
                  <div class="chosen-tags" id="chosen-tags"></div>
                  <div class="tag-input-wrap">
                    <input id="tag-input" placeholder="Type a tag…" autocomplete="off">
                    <div class="suggestions" id="suggestions"></div>
