    function filterCards() {
      const query = search.value.trim().toLocaleLowerCase();
      let shown = 0;
      cards.forEach(card => {
        const textMatch = card.dataset.search.toLocaleLowerCase().includes(query);
        const tagMatch = selectedTag === 'all' || card.dataset.tags.split(' ').includes(selectedTag);
        const viewMatch = selectedView === 'all' || card.dataset.later === 'true';
        const match = textMatch && tagMatch && viewMatch;
        card.style.display = match ? '' : 'none';
        if (match) shown++;
      });
      count.textContent = `${shown} bookmark${shown === 1 ? '' : 's'}`;
      empty.style.display = shown ? 'none' : 'block';
    }
    search.addEventListener('input', filterCards);
    document.querySelectorAll('.tag-filter').forEach(button => button.addEventListener('click', () => {
      if (button.dataset.view) return;
      selectedTag = button.dataset.tag;
      document.querySelectorAll('.tag-filter[data-tag]').forEach(item => item.classList.toggle('active', item.dataset.tag === selectedTag));
      filterCards();
    }));
    document.querySelectorAll('.view-filter').forEach(button => button.addEventListener('click', () => {
      selectedView = button.dataset.view;
      document.querySelectorAll('.view-filter').forEach(item => item.classList.toggle('active', item === button));
      filterCards();
    }));
    document.querySelectorAll('.later-control').forEach(button => button.addEventListener('click', () => {
      const card = button.closest('.card');
      const marked = card.dataset.later === 'true';
      card.dataset.later = marked ? 'false' : 'true';
      button.classList.toggle('marked', !marked);
      button.textContent = marked ? 'Read later' : 'Saved for later';
      button.setAttribute('aria-label', `${marked ? 'Add' : 'Remove'} ${card.querySelector('h2').textContent} ${marked ? 'to' : 'from'} read later`);
      filterCards();
    }));
  </script>
