      cards[0].querySelector('h2').textContent = longTitle;
      cards[0].querySelector('.description').textContent = longDescription;
      cards[0].querySelector('.note').innerHTML = longNote;
      document.querySelector('#edit-full-title').value = longTitle;
      document.querySelector('#edit-full-description').value = longDescription;
      document.querySelector('#edit-full-note').innerHTML = longNote;
    }
    document.querySelector('.edit-long').addEventListener('click', () => document.querySelector('#edit-panel').classList.add('show'));
    document.querySelector('.close-edit').addEventListener('click', () => document.querySelector('#edit-panel').classList.remove('show'));
  </script>
</body>
</html>

