  document.querySelector('#apply-bulk-tag').addEventListener('click',()=>{
    const tag=bulkTagInput.value.trim(); if(!tag) return;
    const selected=selectedCards();
    selected.forEach(card=>{
      const tags=card.dataset.tags.split(' ');
      if(!tags.includes(tag.toLocaleLowerCase())) { card.dataset.tags += ` ${tag.toLocaleLowerCase()}`; const chip=document.createElement('span'); chip.className='card-tag'; chip.textContent=tag; card.querySelector('.card-tags').appendChild(chip); }
    });
    bulkTagModal.classList.remove('show'); clearBulkSelection(); showBulkNotice(`${tag} added to ${selected.length} bookmarks.`);
  });
  document.querySelector('#bulk-later').addEventListener('click',()=>{ const selected=selectedCards(); selected.forEach(card=>card.dataset.later='true'); clearBulkSelection(); showBulkNotice(`${selected.length} bookmarks saved for later.`); });
  document.querySelector('#bulk-archive').addEventListener('click',()=>{ const selected=selectedCards(); selected.forEach(card=>card.dataset.archived='true'); clearBulkSelection(); filterCards(); showBulkNotice(`${selected.length} bookmarks archived.`); });
</script>

