3:const state = { bookmarks:[], tags:[], view:'active', tag:'all', query:'', sort:'newest', selected:new Set(), editing:null, draftTags:[], pendingDelete:[] };
6:  const response=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});
17:  root.querySelectorAll('*').forEach(node=>{ [...node.attributes].forEach(attribute=>node.removeAttribute(attribute.name)); if(!['DIV','P','BR','STRONG','B','UL','OL','LI'].includes(node.tagName) && node.parentNode) node.replaceWith(...node.childNodes); });
20:function normalizedTag(value){ return value.trim().toLocaleLowerCase().replace(/s$/,''); }
23:function closeDialogs(){ $('#scrim').hidden=true; $$('.dialog').forEach(dialog=>dialog.hidden=true); $('#tag-suggestions').classList.remove('show'); $('#bulk-tag-suggestions').classList.remove('show'); }
26:async function load(){ const data=await api('/api/bookmarks'); state.bookmarks=data.bookmarks; state.tags=data.tags; render(); }
30:    const view=state.view==='archive'?item.archived:(!item.archived&&(state.view==='active'||item.readLater));
31:    const tag=state.tag==='all'||item.tags.some(value=>value.toLocaleLowerCase()===state.tag);
32:    const haystack=[item.title,item.description,item.url,strip(item.noteHtml),...(item.tags||[])].join(' ').toLocaleLowerCase();
33:    return view&&tag&&haystack.includes(query);
40:  $('#active-count').textContent=state.bookmarks.filter(item=>!item.archived).length;
41:  $('#later-count').textContent=state.bookmarks.filter(item=>!item.archived&&item.readLater).length;
42:  $('#archive-count').textContent=state.bookmarks.filter(item=>item.archived).length;
44:  renderTags(); renderCards(); renderBulkBar();
46:function renderTags(){
47:  $('#tag-list').innerHTML=state.tags.map(tag=>`<button class="side-item tag-choice ${state.tag===tag.toLocaleLowerCase()?'active':''}" data-tag="${text(tag.toLocaleLowerCase())}">${text(tag)}</button>`).join('');
48:  $('.tag-choice[data-tag="all"]').classList.toggle('active',state.tag==='all');
49:  $$('.tag-choice').forEach(button=>button.addEventListener('click',()=>{ state.tag=button.dataset.tag; render(); }));
57:    if(!state.query&&state.tag==='all'&&state.view==='later'){ title='Nothing saved for later'; copy='Use “Read later” on any bookmark and it will appear here.'; }
58:    if(!state.query&&state.tag==='all'&&state.view==='archive'){ title='Your archive is empty'; copy='Bookmarks you archive will stay safe here until you restore or delete them.'; }
59:    if(!state.query&&state.tag!=='all'){ title='No bookmarks with this tag'; copy='Choose another tag or return to all tags.'; }
70:    <h2><a href="${text(item.url)}" target="_blank" rel="noopener">${text(item.title)}</a></h2>
72:    <div class="tag-chips">${item.tags.map(tag=>`<span class="chip">${text(tag)}</span>`).join('')}</div>
74:    <div class="card-actions"><button data-edit>Edit bookmark</button>${item.archived?`<button data-restore>Restore</button><div class="more"><button data-more>•••</button><div class="more-menu"><button data-delete>Delete permanently</button></div></div>`:`<button data-later>${item.readLater?'Saved for later':'Read later'}</button><button class="archive-action" data-archive>Archive</button>`}</div></div></article>`;
79:    card.querySelector('.pick').addEventListener('change',event=>{ event.target.checked?state.selected.add(id):state.selected.delete(id); render(); });
82:    card.querySelector('[data-archive]')?.addEventListener('click',()=>updateItem(item,{archived:true},'Bookmark archived.'));
83:    card.querySelector('[data-restore]')?.addEventListener('click',()=>updateItem(item,{archived:false},'Bookmark restored.'));
84:    card.querySelector('[data-more]')?.addEventListener('click',event=>event.currentTarget.nextElementSibling.classList.toggle('show'));
85:    card.querySelector('[data-delete]')?.addEventListener('click',()=>askDelete([item]));
88:async function updateItem(item,changes,message){ const data=await api(`/api/bookmarks/${item.id}`,{method:'PUT',body:JSON.stringify(changes)}); Object.assign(item,data.bookmark); if(changes.archived) state.selected.delete(item.id); render(); showNotice(message); }
90:$('#search').addEventListener('input',event=>{ state.query=event.target.value; renderCards(); });
91:$('#sort').addEventListener('change',event=>{ state.sort=event.target.value; renderCards(); });
